/**
 * seed-universe.mjs — Seed (upsert) NSE stocks into the Stock collection.
 * Adds sector, companyName, indices membership, and marketCapTier.
 * Run once: node server/scripts/seed-universe.mjs
 * Safe to re-run — uses upsert so existing docs are preserved (no data loss).
 *
 * Refreshed 2026-07-15 against NSE's official ind_nifty500list.csv /
 * ind_niftymidcap150list.csv (602 unique symbols, up from 334): fixed 6 stale
 * tickers from real corporate actions (TATAMOTORS demerged into TMCV+TMPV;
 * ZOMATO renamed ETERNAL; WELSPUNIND renamed WELSPUNLIV; GMRINFRA's airports
 * business now trades as GMRAIRPORT; PEL split into PIRAMALFIN+PPLPHARMA),
 * removed 3 stale/duplicate entries (NLC, BFINANCE, MINDTREE — each already
 * covered by another entry), deduped 3 symbols that appeared twice in this
 * array (BANKBARODA, ICICIPRULI, SUVENPHAR), and added 268 missing
 * constituents with real sector/company data from the official NSE lists.
 * Mirrors the same-day refresh of python-service/app/services/universe.py
 * (the list that actually drives live scanning) for consistency.
 */

